#!/usr/bin/env bash
# Reps with Rog: is the plan builder API alive? Usage: bash check.sh   (generated by agent/packs.mjs)
set -u
BASE="https://white-label-previews.vercel.app/reps-with-rog"
for u in "$BASE/api/openapi" "$BASE/api/questions?lang=en" "$BASE/api/questions?lang=es" "https://white-label-previews.vercel.app/reps-with-rog/disclaimer.html"; do
  printf '%-70s ' "$u"
  curl -sS -L --max-time 25 -o /dev/null -w 'HTTP %{http_code}\n' "$u" || echo 'NO ANSWER'
done
